    header = [h.strip().lstrip('\ufeff').lower() for h in reader.fieldnames or []]
    missing = [c for c in REQUIRED_COLUMNS if c not in header]
    if missing:
        return ([], [{'row': 1, 'errors': [f"missing columns: {', '.join(missing)}"]}])
    reader.fieldnames = header
    valid, errors, seen = ([], [], set())
    for count, row in enumerate(reader, 1):
        if count > max_rows:
            stop = f'more than {max_rows} rows; stopped'
            errors.append({'row': reader.line_num, 'errors': [stop]})
            break
        name = (row.get('name') or '').strip()
        email = (row.get('email') or '').strip().lower()
        age_raw = (row.get('age') or '').strip()
        local, _, domain = email.partition('@')
        problems = [] if name else ['name is required']
        if None in row:
            problems.append('too many fields')
        if len(email) > MAX_EMAIL_LENGTH or not local or ' ' in email or ('@' in domain) or ('.' not in domain.strip('.')):
            problems.append('email is invalid')
        elif email in seen:
            problems.append('duplicate email')
        if age_raw and (not (age_raw.isdigit() and int(age_raw) <= 150)):
            problems.append('age must be a whole number from 0 to 150')
        if problems:
            errors.append({'row': reader.line_num, 'errors': problems})
        else:
            seen.add(email)
            valid.append({'name': name, 'email': email, 'age': int(age_raw) if age_raw else None})
    return (valid, errors)

def excel_to_csv_text(content: bytes) -> str:
    from openpyxl import load_workbook
    workbook = load_workbook(io.BytesIO(content), read_only=True, data_only=True)
    try:
        sheet = workbook.active
        out = io.StringIO()
        writer = csv.writer(out)
        for cells in sheet.iter_rows(values_only=True):
            values = ['' if v is None else str(v).replace('\r', ' ').replace('\n', ' ') for v in cells]
            writer.writerow(values if any(v.strip() for v in values) else [])
        return out.getvalue()
    finally:
        workbook.close()

def validate_user_upload(content: bytes, filename: str) -> dict[str, Any]:
    name = filename.lower()
    try:
        if name.endswith(('.xlsx', '.xlsm')):
            text = excel_to_csv_text(content)
        elif name.endswith('.csv'):
            text = content.decode('utf-8-sig')
        else:
            return {'valid_count': 0, 'invalid_count': 1, 'invalid_rows': [{'row': 0, 'errors': ['unsupported file type; upload .csv or .xlsx']}]}
    except Exception:
        return {'valid_count': 0, 'invalid_count': 1, 'invalid_rows': [{'row': 0, 'errors': ['file could not be read']}]}
    valid, errors = import_users(text)
    return {'valid_count': len(valid), 'invalid_count': len(errors), 'invalid_rows': errors}

